// --- MORPHING SFERA <-> CUBO (Modalità Implicit) ---
// Usa lo slider A per ingrandire o rimpicciolire la figura

float size = A > 0.0 ? A : 0.8;

// Calcolo distanza per la Sfera
float dSphere = length(p) - size;

// Calcolo distanza per il Cubo (Box esatto)
vec3 d = abs(p) - vec3(size);
float dBox = length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);

// Usiamo il tempo 't' per creare un fattore di interpolazione (da 0 a 1)
// sin(t) va da -1 a 1, quindi lo rimappiamo
float morphFactor = 0.5 + 0.5 * sin(t * 2.0);

// Mixiamo le due forme!
return mix(dSphere, dBox, morphFactor);

